### Step 5: IAU 2000A/B nutation algorithm

`calc_nutation_iau2000ab(jd, model) -> Nutation`. Luni-solar series uses NLS/CLS tables (678 terms for 2000A, 77 for 2000B). Planetary series + P03 correction only for 2000A. **Both loops run in reverse** for numerical stability.

```rust
fn calc_nutation_iau2000ab(jd: f64, model: NutationModel) -> Nutation {
    let t = (jd - J2000) / 36525.0;
    let del = delaunay_iau2000(t);
    let [m, sm, f, d, om] = del;

    // --- Luni-solar nutation ---
    let inls = if model == NutationModel::IAU2000B { NLS_2000B } else { NLS_COUNT };
    let mut dpsi = 0.0_f64;
    let mut deps = 0.0_f64;
    for i in (0..inls).rev() {
        let n = &NLS[i];
        let c = &CLS[i];
        let darg = normalize_radians(
            n[0] as f64 * m + n[1] as f64 * sm + n[2] as f64 * f
            + n[3] as f64 * d + n[4] as f64 * om);
        let (sinarg, cosarg) = (darg.sin(), darg.cos());
        dpsi += (c[0] as f64 + c[1] as f64 * t) * sinarg + c[2] as f64 * cosarg;
        deps += (c[3] as f64 + c[4] as f64 * t) * cosarg + c[5] as f64 * sinarg;
    }
    let mut nutlo_0 = dpsi * O1MAS2DEG;    // 0.1 μas → degrees
    let mut nutlo_1 = deps * O1MAS2DEG;

    // --- Planetary nutation + P03 correction (2000A only) ---
    if model == NutationModel::IAU2000A {
        let pa = planetary_args_iau2000(t);
        dpsi = 0.0;
        deps = 0.0;
        for i in (0..NPL_COUNT).rev() {
            let n = &NPL[i];
            let ic = &ICPL[i];
            let mut darg = 0.0;
            for j in 0..14 { darg += n[j] as f64 * pa[j]; }
            let darg = normalize_radians(darg);
            let (sinarg, cosarg) = (darg.sin(), darg.cos());
            dpsi += ic[0] as f64 * sinarg + ic[1] as f64 * cosarg;
            deps += ic[2] as f64 * sinarg + ic[3] as f64 * cosarg;
        }
        nutlo_0 += dpsi * O1MAS2DEG;
        nutlo_1 += deps * O1MAS2DEG;

        // P03 precession correction (Capitaine et al. 2005), in microarcseconds
        let dpsi_p03 = -8.1 * om.sin() - 0.6 * (2.0*f - 2.0*d + 2.0*om).sin()
            + t * (47.8 * om.sin() + 3.7 * (2.0*f - 2.0*d + 2.0*om).sin()
                   + 0.6 * (2.0*f + 2.0*om).sin() - 0.6 * (2.0*om).sin());
        let deps_p03 = t * (-25.6 * om.cos() - 1.6 * (2.0*f - 2.0*d + 2.0*om).cos());
        nutlo_0 += dpsi_p03 / (3600.0 * 1_000_000.0);  // μas → degrees
        nutlo_1 += deps_p03 / (3600.0 * 1_000_000.0);
    }

    Nutation { dpsi: nutlo_0 * DEGTORAD, deps: nutlo_1 * DEGTORAD }
}
```

### Step 6: Woolard nutation algorithm

`calc_nutation_woolard(jd) -> Nutation`. Simple direct expansion — 13 dpsi terms, 9 deps terms. Uses J1900 epoch. **Critical**: the fractional part uses C `(long)a` truncation toward zero — in Rust, `(a as i64) as f64`, NOT `a.floor()`.

```rust
fn calc_nutation_woolard(jd: f64) -> Nutation {
    let t = (jd - J1900) / 36525.0;
    let t2 = t * t;
    let frac = |x: f64| -> f64 { x - (x as i64 as f64) };
    let ls = 279.697 + 0.000303 * t2 + 360.0 * frac(100.0021358 * t);
    let ld = 270.434 - 0.001133 * t2 + 360.0 * frac(1336.855231 * t);
    let ms = 358.476 - 0.00015  * t2 + 360.0 * frac(99.99736056000026 * t);
    let md = 296.105 + 0.009192 * t2 + 360.0 * frac(13255523.59 * t);
    let nm = 259.183 + 0.002078 * t2 - 360.0 * frac(5.372616667 * t);
    // Convert to radians
    let tls = 2.0 * ls * DEGTORAD;
    let nm  = nm * DEGTORAD;
    let tnm = 2.0 * nm;
    let ms  = ms * DEGTORAD;
    let tld = 2.0 * ld * DEGTORAD;
    let md  = md * DEGTORAD;
    // 13 dpsi terms, 9 deps terms (arcseconds)
    let dpsi = (-17.2327 - 0.01737*t)*nm.sin() + (-1.2729 - 0.00013*t)*tls.sin()
        + 0.2088*tnm.sin() - 0.2037*tld.sin() + (0.1261 - 0.00031*t)*ms.sin()
        + 0.0675*md.sin() - (0.0497 - 0.00012*t)*(tls+ms).sin()
        - 0.0342*(tld-nm).sin() - 0.0261*(tld+md).sin() + 0.0214*(tls-ms).sin()
        - 0.0149*(tls-tld+md).sin() + 0.0124*(tls-nm).sin() + 0.0114*(tld-md).sin();
    let deps = (9.21 + 0.00091*t)*nm.cos() + (0.5522 - 0.00029*t)*tls.cos()
        - 0.0904*tnm.cos() + 0.0884*tld.cos() + 0.0216*(tls+ms).cos()
        + 0.0183*(tld-nm).cos() + 0.0113*(tld+md).cos() - 0.0093*(tls-ms).cos()
        - 0.0066*(tls-nm).cos();
    Nutation { dpsi: dpsi / 3600.0 * DEGTORAD, deps: deps / 3600.0 * DEGTORAD }
}
```

### Step 7: Router function

`pub fn nutation(jd, flags, models) -> Nutation`. Same JPLHOR detection pattern as `precession.rs:40-43`. Three paths: JPLHOR (IAU 1980 + EOP stub), JPLHOR_APPROX (IAU 1980 + constant offsets), normal dispatch by model. JPLHORA_V2 offset applies to IAU 2000 in normal dispatch path.

```rust
pub fn nutation(jd: f64, flags: CalcFlags, models: &AstroModels) -> Nutation {
    let is_jplhor = flags.contains(CalcFlags::DPSIDEPS_1980)
        || (flags.contains(CalcFlags::JPLHOR_APPROX)
            && models.jplhora_mode == JplHoraMode::V3
            && jd <= DPSI_DEPS_IAU1980_TJD0_HORIZONS);
    if is_jplhor {
        let mut nut = calc_nutation_iau1980(jd, NutationModel::IAU1980);
        if !flags.contains(CalcFlags::DPSIDEPS_1980) {
            // JPLHOR_APPROX: constant offsets at Horizons epoch
            nut.dpsi += DPSI_IAU1980_TJD0 / 3600.0 * DEGTORAD;
            nut.deps += DEPS_IAU1980_TJD0 / 3600.0 * DEGTORAD;
        }
        // DPSIDEPS_1980: EOP Bessel interpolation not yet implemented (needs file I/O)
        return nut;
    }
    let model = models.nutation;
    let mut nut = match model {
        NutationModel::IAU1980 | NutationModel::IAUCorr1987 =>
            calc_nutation_iau1980(jd, model),
        NutationModel::IAU2000A | NutationModel::IAU2000B =>
            calc_nutation_iau2000ab(jd, model),
        NutationModel::Woolard =>
            calc_nutation_woolard(jd),
    };
    // JPLHORA_V2 offset for IAU 2000 models (C: swephlib.c:2106-2109)
    if matches!(model, NutationModel::IAU2000A | NutationModel::IAU2000B)
        && flags.contains(CalcFlags::JPLHOR_APPROX)
        && models.jplhora_mode == JplHoraMode::V2
    {
        nut.dpsi += -41.7750 / 3600.0 / 1000.0 * DEGTORAD;
        nut.deps +=  -6.8192 / 3600.0 / 1000.0 * DEGTORAD;
    }
    nut
}
```

